SourceCode.Declaration:
/// <summary>
/// listTransferOrders fills Orders, listPickedSerials fills Serials.
/// </summary>
[DataContractAttribute]
class HSMobileOpsTransferListResponse
{
    boolean    success;
    str        errorCode;
    List       orders;
    List       serials;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Orders'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsTransferSummaryRow))]
public List parmOrders(List _value = orders)
{
    orders = _value;
    return orders;
}

[DataMemberAttribute('Serials'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsSerialHistoryRow))]
public List parmSerials(List _value = serials)
{
    serials = _value;
    return serials;
}
